import datetime,hashlib,json,os,shutil,subprocess,sys,time
from pathlib import Path
out=Path(sys.argv[1]);os.nice(10)
def read(path):return json.loads(path.read_text())
def put(path,value):
 value['checked_at']=datetime.datetime.now().astimezone().isoformat()
 temp=path.with_name(path.name+'.pipeline.tmp');temp.write_text(json.dumps(value,indent=2)+'\n');temp.replace(path)
def status(value,overall=False):
 put(out/'PIPELINE_STATUS.json',value)
 if overall:put(out/'STATUS.json',dict(value))
stage='waiting'
try:
 while True:
  state=read(out/'STATUS.json')
  if state['status'] in ('training_completed_evaluation_pending','evaluating'):break
  if state['status']=='failed':raise RuntimeError('Training failed; no evaluation or promotion')
  status(dict(status='waiting_for_matched_training',training=state,pid=os.getpid()))
  os.kill(read(out/'LAUNCH.json')['pid'],0);time.sleep(20)
 status(dict(status='evaluating',main_training_modified=False,pid=os.getpid()),True)
 commands=read(out/'PIPELINE_LAUNCH.json')['commands']
 for stage,command in enumerate(commands):
  status(dict(status='running',stage=stage,command=command,pid=os.getpid()))
  subprocess.run(command,check=True)
 server=None
 # Visualization is a durable CPU service. Keep prior viewers running.
 try:
  import socket
  with socket.socket() as probe:probe.bind(('127.0.0.1',8802))
 except OSError:
  server=dict(status='not_started_port_in_use',port=8802)
 else:
  command=read(out/'PIPELINE_LAUNCH.json')['viewer_command']
  with (out/'visuals/server.log').open('a') as log:
   process=subprocess.Popen(command,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
  for _ in range(40):
   if process.poll() is not None:raise RuntimeError('Viewer exited: '+str(process.returncode))
   record=out/'visuals/SERVER.json'
   if record.exists() and read(record).get('pid')==process.pid:
    server=read(record);break
   time.sleep(1)
  if server is None:raise RuntimeError('Viewer readiness timeout')
 result=dict(status='completed',main_training_modified=False,automatic_promotion=False,
  free_disk_after_bytes=shutil.disk_usage(out).free,report=str(out/'evaluation/REPORT_zh.md'),
  cpu_recheck=str(out/'evaluation/CPU_RECHECK_all.json'),visualization=server)
 status(result,True)
except BaseException as exc:
 status(dict(status='failed',stage=stage,error=repr(exc),pid=os.getpid()),True)
 raise
